// ❌ Smell: every new notification type edits this method (and its tests).
public string Render(Notification n) => n.Type switch {
    NotificationType.Email    => $"<b>{n.Body}</b>",
    NotificationType.Sms      => n.Body.Length > 160 ? n.Body[..157] + "..." : n.Body,
    NotificationType.Push     => $"{n.Title}: {n.Body}",
    _ => throw new NotSupportedException()
};
// Plus another switch in Send(), another in FormatForPreview()... shotgun surgery.

// ✅ Refactored: each type owns its rendering; adding a type touches one file.
public interface INotificationContent {
    string Render(Notification n);
}
public sealed class EmailContent : INotificationContent {
    public string Render(Notification n) => $"<b>{n.Body}</b>";
}
public sealed class SmsContent : INotificationContent {
    public string Render(Notification n)
        => n.Body.Length > 160 ? n.Body[..157] + "..." : n.Body;
}
// Registry maps type -> behavior; new type = new class, zero edits to existing ones (OCP).
